# Log Brew in three screens: Choose → Dial in → (brew) → How was it?
from playwright.sync_api import sync_playwright
import json, sys, datetime
errs=[]; res=[]
def ok(n,c,i=''):
    res.append(bool(c)); print(('ok  ' if c else 'FAIL'), n, '' if c else i)
d=lambda n:(datetime.date.today()-datetime.timedelta(days=n)).isoformat()
seed={'coffees':[{'id':'c1','name':'Supernova','roaster':'Manhattan','roastDate':d(18)},{'id':'c2','name':'Red Brick','roaster':'Square Mile','roastDate':d(9)}],'recipes':[]}
st=lambda pg: json.loads(pg.evaluate("localStorage.getItem('dialin_v2')"))
vis=lambda pg,s: pg.is_visible(s)
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_context(**p.devices['Pixel 7']).new_page(); pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto('http://localhost:8765/dialed/index.html'); pg.evaluate("s=>localStorage.setItem('dialin_v2', s)", json.dumps(seed)); pg.reload(); pg.wait_for_timeout(600)
    pg.tap('.fab'); pg.wait_for_timeout(300); pg.tap('#modal-fab button:has-text("Log Brew")'); pg.wait_for_timeout(500)
    ok('opens on Choose: step 1 of 3, numbers and tasting hidden', 'Step 1 of 3' in pg.inner_text('#r-step-label') and vis(pg,'#coffee-selector') and not vis(pg,'#r-dose') and not vis(pg,'#r-notes'))
    ok('Choose footer: Cancel + Next ›, no back', vis(pg,'#r-next-btn') and vis(pg,'#r-foot-choose button:has-text("Cancel")') and not vis(pg,'#r-start-btn') and not vis(pg,'#r-back-setup'))
    ok('three progress bars, first lit', pg.evaluate("[...document.querySelectorAll('#r-prog i')].map(i=>i.classList.contains('on'))")==[True,False,False])
    ok('coffee and grinder show only the current choice', pg.evaluate("[...document.querySelectorAll('#coffee-selector .coffee-selector-item')].filter(e=>e.offsetParent).length")==1 and pg.evaluate("[...document.querySelectorAll('#grinder-selector .coffee-selector-item')].filter(e=>e.offsetParent).length")==1)
    pg.locator('#coffee-selector .coffee-selector-item.selected').tap(); pg.wait_for_timeout(200)
    ok('tapping it opens the full list (oldest roast first)', pg.evaluate("[...document.querySelectorAll('#coffee-selector .coffee-selector-item')].filter(e=>e.offsetParent).length")==2)
    pg.locator('#coffee-selector .coffee-selector-item', has_text='Red Brick').tap(); pg.wait_for_timeout(200)
    ok('picking one selects it and closes the list', pg.evaluate("state.selectedCoffeeId")=='c2' and pg.evaluate("[...document.querySelectorAll('#coffee-selector .coffee-selector-item')].filter(e=>e.offsetParent).length")==1)
    ok('methods on one row', pg.evaluate("(()=>{const t=[...document.querySelectorAll('#method-tabs .method-tab')]; return new Set(t.map(x=>Math.round(x.getBoundingClientRect().top))).size})()")==1)
    pg.locator('#modal-recipe .method-tab', has_text='Pourover').first.tap(); pg.wait_for_timeout(200)
    if len(sys.argv)>1: pg.screenshot(path='shots/three_choose.png')
    gname=pg.evaluate("(GRINDERS.find(g=>/comandante/i.test(g.model) && grinderScale(g)) || GRINDERS.find(g=>!g.stepless && grinderScale(g))).model")
    pg.locator('#grinder-selector .coffee-selector-item.selected').tap(); pg.wait_for_timeout(200)
    pg.evaluate(f"[...document.querySelectorAll('#grinder-selector .coffee-selector-item')].find(d=>d.querySelector('.cs-name').textContent==={json.dumps(gname)}).click()"); pg.wait_for_timeout(200)
    pg.tap('#r-next-btn'); pg.wait_for_timeout(300)
    ok('Next › → Dial in: step 2 of 3 with the numbers', 'Step 2 of 3' in pg.inner_text('#r-step-label') and vis(pg,'#r-dose') and not vis(pg,'#coffee-selector') and vis(pg,'#r-back-setup'))
    ds=pg.inner_text('#r-dial-summary'); ok('Dial in summary shows coffee and method', 'Red Brick' in ds and 'Pourover' in ds, ds)
    ok('footer: Skip timer + Start brew; no timer card yet', vis(pg,'#r-skip-btn') and pg.inner_text('#r-start-btn').lower().endswith('start brew') and not vis(pg,'#brew-timer-toggle') and not vis(pg,'#r-save-btn'))
    bx=pg.evaluate("""(()=>{const b=document.getElementById('r-start-btn'), r=b.getBoundingClientRect(), t=document.createRange(); t.selectNodeContents(b); const q=t.getBoundingClientRect();
      return {h:r.height, w:r.width, vw:innerWidth, dx:Math.abs((q.left+q.right)/2-(r.left+r.right)/2), dy:Math.abs((q.top+q.bottom)/2-(r.top+r.bottom)/2), lines:new Set([...t.getClientRects()].map(x=>Math.round(x.top))).size}})()""")
    ok('Start brew is large', bx['h']>=56 and bx['w']>=bx['vw']*0.5, bx)
    ok('Start brew text is centred both ways on one line', bx['dx']<=2 and bx['dy']<=2 and bx['lines']<=1, bx)
    ok('footer stays on screen while scrolling', pg.evaluate("(()=>{const m=document.querySelector('#modal-recipe .modal'); m.scrollTop=9999; const r=document.getElementById('r-start-btn').getBoundingClientRect(); return r.bottom<=innerHeight+1 && r.top>innerHeight-140})()"))
    pg.evaluate("document.querySelector('#modal-recipe .modal').scrollTop=0")
    g=pg.evaluate("""(()=>{const r=document.getElementById('r-grind-range'), g=selectedGrinder(), sc=grinderScale(g), b=document.getElementById('r-grind-band'), tr=r.getBoundingClientRect(), bb=b.getBoundingClientRect();
      return {min:+r.min, max:+r.max, s0:sc.s0, s1:sc.s1, band:!b.hidden, bl:bb.left-tr.left, br:bb.right-tr.left, tw:tr.width, sug:document.getElementById('r-grind-sug').innerText, cfg:brewGrindSlider(), hint:document.getElementById('r-grind-hint').innerText, dis:r.disabled}})()""")
    ok('grind slider spans the grinder\'s whole range', g['min']<=g['s0']+1e-9 and g['max']>=g['s1']-1e-9 and g['max']-g['min']>=(g['s1']-g['s0'])*0.99 and 'full grinder range' in g['hint'].lower(), g)
    c=g['cfg']; span=c['hi']-c['lo']
    ok('suggested band drawn over the usual Pourover range', g['band'] and c['band'] and c['lo']<c['band']['lo']<c['band']['hi']<=c['hi'] and abs((g['bl']+7-11)/(g['tw']-22) - (c['band']['lo']-c['lo'])/span)<0.03 and abs((g['br']-7-11)/(g['tw']-22) - (c['band']['hi']-c['lo'])/span)<0.03, g)
    ok('key reads "Suggested for Pourover · a–b"', g['sug'].startswith('Suggested for Pourover') and f"{c['band']['lo']}–{c['band']['hi']}" in g['sug'], g['sug'])
    pg.evaluate(f"(()=>{{const r=document.getElementById('r-grind-range'); r.value={c['lo']}; r.dispatchEvent(new Event('input',{{bubbles:true}}))}})()"); pg.wait_for_timeout(100)
    ok('slider can reach the finest setting', float(pg.input_value('#r-grind'))==c['lo'], pg.input_value('#r-grind'))
    pg.fill('#r-grind', str(c['band']['lo'])); pg.dispatch_event('#r-grind','input'); pg.wait_for_timeout(100)
    ok('typing a value still works and moves the slider', float(pg.eval_on_selector('#r-grind-range','e=>e.value'))==c['band']['lo'])
    if len(sys.argv)>1: pg.screenshot(path='shots/three_dial.png')
    pg.tap('#r-back-setup'); pg.wait_for_timeout(200); ok('‹ Back on Dial in → Choose', vis(pg,'#coffee-selector') and not vis(pg,'#r-dose'))
    pg.locator('#modal-recipe .method-tab', has_text='AeroPress').tap(); pg.tap('#r-next-btn'); pg.wait_for_timeout(200)
    pg.fill('#r-dose','12'); pg.fill('#r-yield','200'); pg.fill('#r-temp','90')
    # brew
    pg.tap('#r-start-btn'); pg.wait_for_timeout(400); ok('Start brew opens brew mode', vis(pg,'#brew-mode'))
    pg.evaluate("brewTimer.startedAt=Date.now()-150000"); pg.wait_for_timeout(300); pg.tap('.bm-min'); pg.wait_for_timeout(300)
    ok('minimised: timer card appears, footer offers Back to the timer', vis(pg,'#brew-timer-toggle') and 'back to the timer' in pg.inner_text('#r-start-btn').lower())
    pg.tap('#r-start-btn'); pg.wait_for_timeout(300); ok('Back to the timer reopens brew mode', vis(pg,'#brew-mode'))
    pg.tap('#bm-stop'); pg.wait_for_timeout(400); pg.tap('#modal-brew-done button:has-text("Score now")'); pg.wait_for_timeout(500)
    ok('after Stop → Score now: How was it? (step 3 of 3)', 'Step 3 of 3' in pg.inner_text('#r-step-label') and vis(pg,'#modal-recipe .extraction-picker') and not vis(pg,'#r-dose') and vis(pg,'#r-save-btn') and vis(pg,'#r-later-btn'))
    s=pg.inner_text('#r-summary')
    ok('summary strip shows the brew', all(x in s for x in ['Red Brick','AeroPress','12g → 200ml','90°C','2:3']), s)
    pg.tap('#modal-recipe .extraction-btn.good'); pg.fill('#r-notes','Sweet')
    pg.tap('#r-back-setup'); pg.wait_for_timeout(200)
    ok('‹ Back returns to Dial in with everything kept', vis(pg,'#r-dose') and pg.input_value('#r-dose')=='12' and pg.input_value('#r-notes')=='Sweet' and pg.evaluate("state.selectedExtraction")=='good')
    ok('with a time recorded, the footer says Next ›', pg.inner_text('#r-start-btn').lower().startswith('next') and not vis(pg,'#r-skip-btn'))
    pg.tap('#r-start-btn'); pg.wait_for_timeout(200); ok('Next › goes to step 3', vis(pg,'#r-notes'))
    pg.go_back(); pg.wait_for_timeout(400); ok('phone Back on step 3 returns to step 2 (sheet stays open)', vis(pg,'#r-dose') and pg.locator('#modal-recipe.open').count()==1)
    pg.go_back(); pg.wait_for_timeout(400); ok('phone Back on step 2 returns to step 1', vis(pg,'#coffee-selector') and pg.locator('#modal-recipe.open').count()==1)
    pg.tap('#r-next-btn'); pg.wait_for_timeout(200)
    pg.tap('#r-start-btn'); pg.wait_for_timeout(200); pg.keyboard.press('Escape'); pg.wait_for_timeout(300); ok('Escape on step 3 also returns to step 2', vis(pg,'#r-dose'))
    pg.tap('#r-start-btn'); pg.wait_for_timeout(200)
    if len(sys.argv)>1: pg.screenshot(path='shots/two_taste.png')
    pg.tap('#r-save-btn'); pg.wait_for_timeout(1000)
    r=st(pg)['recipes']; ok('Save brew saves everything from both screens', len(r)==1 and str(r[0]['dose'])=='12' and str(r[0]['temp'])=='90' and r[0]['extraction']=='good' and r[0]['notes']=='Sweet' and r[0]['coffeeId']=='c2' and int(r[0]['time'])>=149, r)
    pg.evaluate("document.querySelectorAll('.modal-overlay.open').forEach(m=>closeModal(m.id))"); pg.wait_for_timeout(400)
    # skip timer
    pg.evaluate("openRecipeModal()"); pg.wait_for_timeout(400)
    ok('next Log Brew starts back on step 1', vis(pg,'#coffee-selector') and 'Step 1' in pg.inner_text('#r-step-label'))
    pg.tap('#r-next-btn'); pg.wait_for_timeout(200); pg.tap('#r-skip-btn'); pg.wait_for_timeout(200); ok('Skip timer goes straight to step 3', vis(pg,'#r-notes'))
    pg.fill('#r-dose','') if vis(pg,'#r-dose') else None
    pg.evaluate("document.getElementById('r-dose').value='-5'"); pg.tap('#r-save-btn'); pg.wait_for_timeout(400)
    ok('a problem with the numbers sends you back to Dial in with the message', vis(pg,'#r-dose') and 'dose' in pg.inner_text('#toast').lower())
    pg.evaluate("document.querySelectorAll('.modal-overlay.open').forEach(m=>closeModal(m.id))"); pg.wait_for_timeout(400)
    # edit
    pg.evaluate(f"editBrew('{r[0]['id']}')"); pg.wait_for_timeout(500)
    ok('editing opens on Choose', vis(pg,'#coffee-selector'))
    pg.tap('#r-next-btn'); pg.wait_for_timeout(200)
    ok('editing: Dial in with Next ›, no Skip timer', vis(pg,'#r-dose') and pg.inner_text('#r-start-btn').lower().startswith('next') and not vis(pg,'#r-skip-btn'))
    pg.tap('#r-start-btn'); pg.wait_for_timeout(200); ok('Next › shows the saved tasting', pg.input_value('#r-notes')=='Sweet')
    pg.evaluate("document.querySelectorAll('.modal-overlay.open').forEach(m=>closeModal(m.id))"); pg.wait_for_timeout(400)
    pg.evaluate(f"repeatBrew && repeatBrew('{r[0]['id']}')") if pg.evaluate("typeof repeatBrew==='function'") else None; pg.wait_for_timeout(400)
    if pg.locator('#modal-recipe.open').count(): ok('Repeat opens straight on Dial in', vis(pg,'#r-dose') and 'Step 2' in pg.inner_text('#r-step-label'))
    pg.evaluate("document.querySelectorAll('.modal-overlay.open').forEach(m=>closeModal(m.id)); state.grinders=[]; state.selectedGrinderId=null; openRecipeModal(); setBrewPage('dial')"); pg.wait_for_timeout(400)
    pg.evaluate("document.querySelectorAll('.modal-overlay.open').forEach(m=>closeModal(m.id))"); pg.wait_for_timeout(400)
    pg.evaluate("openRecipeModal()"); pg.wait_for_timeout(400); pg.go_back(); pg.wait_for_timeout(400)
    ok('phone Back on step 1 closes Log Brew', pg.locator('#modal-recipe.open').count()==0)
    pg.evaluate("state.grinders=[]; state.selectedGrinderId=null; openRecipeModal(); setBrewPage('dial')"); pg.wait_for_timeout(400)
    ok('no grinder: grind slider disabled, band hidden, setting typed', pg.eval_on_selector('#r-grind-range','e=>e.disabled') and not vis(pg,'#r-grind-band') and pg.is_editable('#r-grind'))
    ok('no page errors', not errs, errs)
print(sum(res),'/',len(res)); sys.exit(0 if all(res) else 1)
